## Event-Driven Communication

```xiom
pub interface Observer[T] {
  fn on_notify(self: &Self, event: &T);
}

pub type EventBus[T] = {
  subscribers: Vec[Box[dyn Observer[T]]];
}

impl EventBus[T] {
  fn new() -> EventBus[T] {
    return EventBus{ subscribers: Vec[Box[dyn Observer[T]]]() };
  }

  fn subscribe(self: &mut EventBus[T], observer: Box[dyn Observer[T]]) {
    self.subscribers.push(observer);
  }

  fn notify(self: &EventBus[T], event: &T) {
    for subscriber in &self.subscribers {
      subscriber.on_notify(event);
    }
  }
}

// Concrete observers
pub type Logger = {};
impl Observer[Str] for Logger {
  fn on_notify(self: &Logger, event: &Str) {
    io.println("[LOG]: " + event);
  }
}

pub type Metrics = { error_count: Int; }
impl Observer[Str] for Metrics {
  fn on_notify(self: &mut Metrics, event: &Str) {
    if event.contains("ERROR") {
      self.error_count = self.error_count + 1;
    }
  }
}

fn main() {
  let mut bus = EventBus[Str]::new();
  bus.subscribe(Box::new(Logger{}));
  bus.subscribe(Box::new(Metrics{ error_count: 0 }));

  bus.notify(&"User logged in");
  bus.notify(&"ERROR: Connection failed");
}
```

### Strongly Typed Events

```xiom
pub enum AppEvent {
  UserLogin(username: Str),
  FileSaved(path: Str),
  Error(message: Str, code: Int),
}

let bus = EventBus[AppEvent]::new();
bus.notify(&AppEvent::UserLogin("alice"));
```

### Callback-Based Observer

```xiom
pub type CallbackObserver[T] = { callback: fn(&T); }

impl Observer[T] for CallbackObserver[T] {
  fn on_notify(self: &CallbackObserver[T], event: &T) {
    (self.callback)(event);
  }
}

bus.subscribe(Box::new(CallbackObserver{ callback: |e| io.println(e) }));
```

