pub type ScoreBoard = {
  score: Int;
  observers: Vec[fn(Int)];
}

impl ScoreBoard {
  fn new() -> ScoreBoard { return ScoreBoard{ score: 0, observers: Vec[fn(Int)]() }; }
  fn on_score_change(self: &mut ScoreBoard, callback: fn(Int)) {
    self.observers.push(callback);
  }
  fn set_score(self: &mut ScoreBoard, new_score: Int) {
    self.score = new_score;
    for obs in &self.observers { obs(self.score); }
  }
}

fn main() -> Int {
  let mut board = ScoreBoard::new();
  board.on_score_change(|s| io.println("Score: " + s.to_str()));
  board.set_score(100);
  return board.score;
}
